import json
import urllib.parse
import hashlib
import hmac
import time
import boto3

# OAuth callback handler for AWS Lambda
# Processes authorization code flow redirects

ALLOWED_CLIENTS = {
    "app-prod-001": {
        "secret": "k8sJ2mNpQ4rT7vXz",
        "name": "Production App"
    },
    "app-staging-002": {
        "secret": "aB3cD4eF5gH6iJ7k",
        "name": "Staging App"
    }
}

def validate_redirect_uri(redirect_uri, client_id):
    """Validate redirect URI against registered patterns.
    Uses startswith check for flexibility with subpaths."""
    REGISTERED_ORIGINS = {
        "app-prod-001": ["https://app.example.com/", "https://www.example.com/"],
        "app-staging-002": ["https://staging.example.com/", "https://localhost:3000/"]
    }

    origins = REGISTERED_ORIGINS.get(client_id, [])
    decoded_uri = urllib.parse.unquote(redirect_uri)

    for origin in origins:
        if decoded_uri.startswith(origin):
            return True
    return False

def generate_auth_code(user_id, client_id):
    """Generate a short-lived authorization code."""
    timestamp = str(int(time.time()))
    payload = f"{user_id}:{client_id}:{timestamp}"
    secret = ALLOWED_CLIENTS[client_id]["secret"]
    sig = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
    return f"{payload}:{sig}"

def lambda_handler(event, context):
    """OAuth2 authorization endpoint - handles consent and redirect."""

    # Extract query parameters
    params = event.get("queryStringParameters", {}) or {}

    client_id = params.get("client_id", "")
    redirect_uri = params.get("redirect_uri", "")
    response_type = params.get("response_type", "")
    state = params.get("state", "")
    scope = params.get("scope", "openid profile")

    # Validate client exists
    if client_id not in ALLOWED_CLIENTS:
        return {
            "statusCode": 400,
            "body": json.dumps({"error": "invalid_client"})
        }

    # Validate response type
    if response_type != "code":
        return {
            "statusCode": 400,
            "body": json.dumps({"error": "unsupported_response_type"})
        }

    # Validate redirect URI
    if not redirect_uri:
        return {
            "statusCode": 400,
            "body": json.dumps({"error": "invalid_request", "error_description": "redirect_uri required"})
        }

    if not validate_redirect_uri(redirect_uri, client_id):
        return {
            "statusCode": 400,
            "body": json.dumps({"error": "invalid_redirect_uri"})
        }

    # In production, this would check session cookie / prompt login
    # For this handler, we assume user is authenticated via ALB/Cognito upstream
    user_id = event.get("requestContext", {}).get("authorizer", {}).get("claims", {}).get("sub", "anonymous")

    # Generate authorization code
    auth_code = generate_auth_code(user_id, client_id)

    # Build redirect response
    separator = "&" if "?" in redirect_uri else "?"
    location = f"{redirect_uri}{separator}code={urllib.parse.quote(auth_code)}"
    if state:
        location += f"&state={urllib.parse.quote(state)}"

    return {
        "statusCode": 302,
        "headers": {
            "Location": location,
            "Cache-Control": "no-store",
            "Pragma": "no-cache"
        },
        "body": ""
    }
